 let page=mounted.take_result_page().unwrap();assert!(mounted.acknowledge_result_page(page.token).unwrap());assert!(mounted.granted_retirement_ready());assert_eq!(mounted.pending_child_publication.as_ref().unwrap().phase,PendingChildGroupPublicationPhase::Acknowledged);
